        [](const auto& a, const auto& b) { const int x = std::stoi(a.value), y = std::stoi(b.value); return (x > y) - (x < y); });
}
const stats::Slot* slot(const stats::Column& c, stats::Kind kind) {
    for (const auto& x : c.slots) if (x.kind == kind) return &x;
