        if (!names.empty()) { names += ','; values += ','; }
        names += x.first; values += quote(x.second);
    }
    std::cout << "SCALAR_REFERENCE_SQL INSERT INTO " << table << '(' << names << ") VALUES(" << values << ");\n";
