        require(find(sampled, stats::Kind::Histogram)->values->cells.size() == 2 &&
            find(sampled, stats::Kind::Correlation)->numbers->at(0) == 1, "sample uses physical ranks and target");
        const auto path = std::filesystem::absolute(g_engine.dbPath(db) / ".analyzed_statistics");
        const auto image = stats::read(path);
        require(image && image->columns.size() == 15, "one real generation per analyzed owner");
        std::cout << "ANALYZED_SCALAR_IMAGE " << path << '\n';
        std::cout << "ANALYZED_SCALAR_COMPLETE checks=" << checks << " failures=0\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "ANALYZED_SCALAR_FAIL checks=" << checks << ' ' << error.what() << '\n'; return 1;
    }
}

#include "catalog/AnalyzedScalarStatistics.h"
#include <iostream>
#include <stdexcept>

namespace {
namespace stats = dbms::analyzed_statistics;
size_t checks = 0;
void require(bool good, const char* message) {
    ++checks; if (!good) throw std::runtime_error(message);
}
template<class F> void rejected(F action) {
    bool failed = false;
    try { action(); } catch (const dbms::DbError& error) { failed = error.sqlState() == "XX001"; }
    require(failed, "malformed analysis input is rejected with XX001");
}
stats::Column declaration(double population, int target = 3) {
    stats::Column c;
    auto type = std::make_shared<dbms::DatumType>();
    type->actualOid = type->codecOid = 23; type->codecSize = 4;
    c.attributeType = type; c.totalRows = population; c.target = target; c.averageWidth = 4;
    return c;
}
using Samples = std::vector<stats::ScalarSample>;
void append(Samples& rows, std::optional<int> value, bool wide = false, uint32_t width = 4) {
    stats::ScalarSample row; row.ordinal = rows.size();
    row.value = dbms::ExprValue("integer", value ? std::to_string(*value) : "", !value);
    row.storedWidth = width; row.tooWide = wide; rows.push_back(std::move(row));
}
std::optional<stats::Column> collect(stats::Column c, const Samples& sample) {
    return stats::collectScalarStatistics(c, sample, 96, 97,
        [](const auto& a, const auto& b) { const int x = std::stoi(a.value), y = std::stoi(b.value); return (x > y) - (x < y); });
}
const stats::Slot* slot(const stats::Column& c, stats::Kind kind) {
    for (const auto& x : c.slots) if (x.kind == kind) return &x;
    return nullptr;
}
std::vector<std::string> values(const stats::Column& c, stats::Kind kind) {
    const auto* s = slot(c, kind); std::vector<std::string> result;
    if (s && s->values) for (const auto& x : s->values->cells) result.push_back(x.value);
    return result;
}
} // namespace
int main() {
    try {
        Samples sample;
        for (int i = 39; i >= 0; --i) append(sample, i);
        auto c = *collect(declaration(40), sample);
        require(c.distinctEstimate == -1 && c.nullFraction == 0 && c.averageWidth == 4, "full-population unique fields");
        require(values(c, stats::Kind::Histogram) == std::vector<std::string>({"0", "13", "26", "39"}), "target+1 quantiles include actual endpoints");
        require(slot(c, stats::Kind::Correlation)->numbers->at(0) == -1, "reverse physical ranks");
        require(!slot(c, stats::Kind::MostCommon), "singleton groups are not MCV");
        const auto indexed = *stats::collectScalarStatistics(declaration(40), sample, 96, 97, {}, {},
            [&](size_t a, size_t b) { const int x = std::stoi(sample[a].value.value), y = std::stoi(sample[b].value.value); return (x > y) - (x < y); });
        require(values(indexed, stats::Kind::Histogram) == values(c, stats::Kind::Histogram) &&
            slot(indexed, stats::Kind::Correlation)->numbers == slot(c, stats::Kind::Correlation)->numbers,
            "indexed comparison preserves typed value and physical-rank results");
        sample.clear();
        for (int i = 0; i < 15; ++i) append(sample, {});
        for (int i = 0; i < 5; ++i) append(sample, i);
        c = *collect(declaration(20), sample);
        require(c.nullRows == 15 && c.nullFraction == .75f && c.distinctEstimate == -.25f, "high NULL unique fraction");
        require(slot(c, stats::Kind::Correlation)->numbers->at(0) == 1, "NULL rows do not enter sortable ranks");
        sample.clear();
        for (int i = 0; i < 20; ++i) append(sample, 1);
        for (int i = 2; i <= 21; ++i) append(sample, i);
        c = *collect(declaration(40), sample);
        require(values(c, stats::Kind::MostCommon) == std::vector<std::string>{"1"} && slot(c, stats::Kind::MostCommon)->numbers->at(0) == .5f, "MCV frequency includes all rows");
        require(values(c, stats::Kind::Histogram) == std::vector<std::string>({"2", "8", "14", "21"}), "histogram excludes the entire MCV population");
        // Reverse vector slots without changing real scan ordinals. A
        // reservoir owner may replace any slot, but physical correlation and
        // representative/quantile order must remain exactly unchanged.
        std::reverse(sample.begin(), sample.end());
        const auto shuffled = *collect(declaration(40), sample);
        require(values(shuffled, stats::Kind::Histogram) == values(c, stats::Kind::Histogram) &&
            slot(shuffled, stats::Kind::Correlation)->numbers == slot(c, stats::Kind::Correlation)->numbers,
            "reservoir slot order cannot change physical-order statistics");
        sample.clear();
        for (int i = 0; i < 18; ++i) append(sample, 1);
        append(sample, 2); append(sample, 3);
        c = *collect(declaration(1000), sample);
        require(c.distinctEstimate == 3 && values(c, stats::Kind::MostCommon) == std::vector<std::string>{"1"}, "sample estimator and significant common item");
        require(slot(c, stats::Kind::MostCommon)->numbers->at(0) == .9f, "sample frequency denominator");
        sample.clear();
        for (int i = 0; i < 10; ++i) { append(sample, i); append(sample, i); }
        c = *collect(declaration(1000), sample);
        require(c.distinctEstimate == 10 && !slot(c, stats::Kind::MostCommon), "weak incomplete MCV tail is removed");
        sample.clear(); append(sample, 1); append(sample, 1);
        append(sample, 9, true, 1025); append(sample, 9, true, 1025);
        append(sample, {}); append(sample, {});
        c = *collect(declaration(6), sample);
        require(c.averageWidth == 514 && c.distinctEstimate == -.5f, "wide values affect width and singleton estimate");
        require(values(c, stats::Kind::MostCommon) == std::vector<std::string>{"1"} &&
            slot(c, stats::Kind::MostCommon)->numbers->at(0) == 1.0f / 3,
            "wide and NULL rows remain in MCV denominator");
        sample.clear(); for (int i = 0; i < 3; ++i) append(sample, {});
        c = *collect(declaration(3), sample);
        require(c.nullFraction == 1 && c.averageWidth == 4 && c.distinctEstimate == 0 && c.slots.empty(), "fixed-width all NULL applicability");
        require(!collect(declaration(0), {}), "empty table has no invented statistics record");
        require(!collect(declaration(3, 0), sample), "statistics target zero disables collection");
        rejected([&] { collect(declaration(2), sample); });
        rejected([&] { collect(declaration(3, 10001), sample); });
        sample.clear(); append(sample, 1); append(sample, 2); sample.back().ordinal = 0;
        rejected([&] { collect(declaration(2), sample); });
        sample.clear(); append(sample, 1, false, UINT32_MAX);
        rejected([&] { collect(declaration(1), sample); });
        std::cout << "ANALYZED_SCALAR_COLLECTOR checks=" << checks << " failures=0\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << "ANALYZED_SCALAR_COLLECTOR_FAIL checks=" << checks << ' ' << error.what() << '\n'; return 1;
    }
}

#pragma once

#include "catalog/AnalyzedStatistics.h"
#include "common/DbError.h"
#include <algorithm>
#include <cmath>
#include <functional>
#include <limits>
#include <numeric>

namespace dbms::analyzed_statistics {

// Inputs come from one real physical scan. Width is the stored datum's byte
// span, not its display length; wide values still contribute to width/NULL
// statistics but need not retain their payload. The scan ordinal survives
// reservoir replacement and is unrelated to the sample vector's position.
struct ScalarSample {
    uint64_t ordinal = 0;
    ExprValue value;
    uint32_t storedWidth = 0;
    bool tooWide = false;
};

// The caller supplies resolved equality/ordering roles and a comparator for
// the actual declaration/collation. No lexical fallback for unknown types.
// The formulas and slot applicability follow PostgreSQL REL_18_6 analyze.c;
// storage widths and the sampling owner belong to this engine.
inline std::optional<Column> collectScalarStatistics(
    Column column, const std::vector<ScalarSample>& sample,
    uint32_t equalityOperator, uint32_t orderingOperator,
    const std::function<int(const ExprValue&, const ExprValue&)>& compare,
    const std::function<void()>& interrupt = {}) {
    if (!column.attributeType || !column.attributeType->actualOid ||
        column.target < 0 || column.target > 10000 ||
        !std::isfinite(column.totalRows) || column.totalRows < sample.size())
        throw DbError("XX001", "invalid scalar statistics analysis input");
    if (!column.target || sample.empty()) return std::nullopt;
    if (!equalityOperator || !orderingOperator || !compare)
        throw DbError("XX001", "scalar statistics comparison role is absent");
    column.sampleRows = sample.size();
    column.nullRows = 0;
    column.slots.clear();
    uint64_t totalWidth = 0;
    size_t nonnull = 0, wide = 0;
    std::vector<size_t> values;
    values.reserve(sample.size());
    for (size_t i = 0; i < sample.size(); ++i) {
        if (interrupt && (i & 1023U) == 0) interrupt();
        const auto& cell = sample[i];
        if (cell.value.isNull) { ++column.nullRows; continue; }
        ++nonnull;
        totalWidth += cell.storedWidth;
        if (cell.tooWide) ++wide;
        else values.push_back(i);
    }
    column.nullFraction = double(column.nullRows) / sample.size();
    if (nonnull) column.averageWidth = static_cast<int32_t>(totalWidth / nonnull);
    column.distinctEstimate = 0;
    if (values.empty()) {
        if (nonnull) column.distinctEstimate = -(1.0 - column.nullFraction);
        return column;
    }

    // Physical rank includes only sortable non-NULL, non-wide sample values,
    // just as PG's values_cnt. A tie uses the original scan rank.
    std::sort(values.begin(), values.end(), [&](size_t a, size_t b) {
        return sample[a].ordinal < sample[b].ordinal;
    });
    std::vector<size_t> rank(sample.size());
    for (size_t i = 0; i < values.size(); ++i) {
        if (i && sample[values[i - 1]].ordinal == sample[values[i]].ordinal)
            throw DbError("XX001", "duplicate scalar statistics sample ordinal");
        rank[values[i]] = i;
    }
    size_t comparisons = 0;
    std::sort(values.begin(), values.end(), [&](size_t a, size_t b) {
        if (interrupt && (++comparisons & 1023U) == 0) interrupt();
        const int result = compare(sample[a].value, sample[b].value);
        return result ? result < 0 : rank[a] < rank[b];
    });
    struct Group { size_t first, count; };
    std::vector<Group> groups;
    double xy = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        if (interrupt && (i & 1023U) == 0) interrupt();
        xy += double(i) * rank[values[i]];
        if (i && compare(sample[values[i - 1]].value, sample[values[i]].value) == 0)
            ++groups.back().count;
        else groups.push_back({i, 1});
    }
    const size_t repeated = std::count_if(groups.begin(), groups.end(),
        [](const Group& g) { return g.count > 1; });
    if (!repeated) column.distinctEstimate = -(1.0 - column.nullFraction);
    else if (!wide && repeated == groups.size()) column.distinctEstimate = groups.size();
    else {
        const double singleton = groups.size() - repeated + wide;
        const double distinct = singleton + repeated;
        const double population = column.totalRows * (1.0 - column.nullFraction);
        double estimate = nonnull * distinct /
            ((nonnull - singleton) + singleton * nonnull / population);
        estimate = std::min(population, std::max(distinct, estimate));
        column.distinctEstimate = std::floor(estimate + 0.5);
    }
    if (column.distinctEstimate > 0.1 * column.totalRows)
        column.distinctEstimate = -(column.distinctEstimate / column.totalRows);

    std::vector<size_t> common;
    for (size_t i = 0; i < groups.size(); ++i)
        if (groups[i].count > 1) common.push_back(i);
    std::stable_sort(common.begin(), common.end(), [&](size_t a, size_t b) {
        return groups[a].count > groups[b].count;
    });
    if (common.size() > static_cast<size_t>(column.target)) common.resize(column.target);
    // The full population needs no significance filter. For a sample, retain
    // a complete finite-domain list, or remove statistically weak tail items.
    const bool complete = common.size() == groups.size() && !wide &&
        column.distinctEstimate > 0;
    if (!complete && column.sampleRows != column.totalRows && column.totalRows > 1) {
        double populationDistinct = column.distinctEstimate;
        if (populationDistinct < 0) populationDistinct *= -column.totalRows;
        double preceding = 0;
        for (size_t i = 0; i + 1 < common.size(); ++i) preceding += groups[common[i]].count;
        while (!common.empty()) {
            double selectivity = std::clamp(1.0 - preceding / column.sampleRows -
                column.nullFraction, 0.0, 1.0);
            const double remaining = populationDistinct - (common.size() - 1);
            if (remaining > 1) selectivity /= remaining;
            const double count = groups[common.back()].count;
            const double population = column.totalRows, n = column.sampleRows;
            const double success = population * count / n;
            const double variance = n * success * (population - success) *
                (population - n) / (population * population * (population - 1));
            if (count > selectivity * n + 2 * std::sqrt(variance) + 0.5) break;
            common.pop_back();
            if (!common.empty()) preceding -= groups[common.back()].count;
        }
    }
    std::vector<bool> isCommon(groups.size(), false);
    if (!common.empty()) {
        Slot mcv; mcv.kind = Kind::MostCommon;
        mcv.comparisonOperator = equalityOperator; mcv.collation = column.collation;
        mcv.numbers.emplace(); mcv.values = Values{column.attributeType, {}};
        for (size_t g : common) {
            isCommon[g] = true;
            mcv.numbers->push_back(double(groups[g].count) / column.sampleRows);
            mcv.values->cells.push_back(sample[values[groups[g].first]].value);
        }
        column.slots.push_back(std::move(mcv));
    }
    size_t bounds = groups.size() - common.size();
    if (bounds > static_cast<size_t>(column.target)) bounds = column.target + 1;
    if (bounds >= 2) {
        std::vector<size_t> residual;
        for (size_t g = 0; g < groups.size(); ++g) if (!isCommon[g])
            for (size_t i = groups[g].first; i < groups[g].first + groups[g].count; ++i)
                residual.push_back(values[i]);
        Slot histogram; histogram.kind = Kind::Histogram;
        histogram.comparisonOperator = orderingOperator; histogram.collation = column.collation;
        histogram.values = Values{column.attributeType, {}};
        const size_t whole = (residual.size() - 1) / (bounds - 1);
        const size_t fraction = (residual.size() - 1) % (bounds - 1);
        size_t position = 0, remainder = 0;
        for (size_t i = 0; i < bounds; ++i) {
            histogram.values->cells.push_back(sample[residual[position]].value);
            position += whole; remainder += fraction;
            if (remainder >= bounds - 1) { ++position; remainder -= bounds - 1; }
        }
        column.slots.push_back(std::move(histogram));
    }
    if (values.size() > 1) {
        const double n = values.size(), sum = (n - 1) * n / 2;
        const double squares = (n - 1) * n * (2 * n - 1) / 6;
        Slot correlation; correlation.kind = Kind::Correlation;
        correlation.comparisonOperator = orderingOperator; correlation.collation = column.collation;
        correlation.numbers = std::vector<float>{float((n * xy - sum * sum) /
            (n * squares - sum * sum))};
        column.slots.push_back(std::move(correlation));
    }
    return column;
}
