inline std::pair<uint32_t, uint32_t> scalarOperators(uint32_t base) {
    // Immutable builtin operator identities for the existing scalar semantics.
    // This does not register pg_operator or resolve user-defined operators.
    switch (base) {
        case 16: return {91, 58};
        case 20: return {410, 412};
        case 21: return {94, 95};
        case 23: return {96, 97};
        case 25: case 1043: return {98, 664};
        case 700: return {620, 622};
        case 701: return {670, 672};
        case 790: return {900, 902};
        case 1042: return {1054, 1058};
        case 1082: return {1093, 1095};
        case 1083: return {1108, 1110};
        case 1114: return {2060, 2062};
        case 1184: return {1320, 1322};
        case 1700: return {1752, 1754};
        case 2950: return {2972, 2974};
        default: return {};
    }
}
inline uint64_t schemaImage(const std::filesystem::path& path) {
    std::ifstream input(path, std::ios::binary);
    if (!input) throw DbError("58030", "could not read analyzed relation schema");
    std::string bytes{std::istreambuf_iterator<char>(input), {}};
    if (input.bad()) throw DbError("58030", "could not read complete analyzed relation schema");
    return codec::checksum(bytes);
}
inline std::string attributeImage(const CatalogManager::MetadataSnapshot& snapshot,
                                  uint32_t relation) {
    std::vector<const PgAttributeRow*> rows;
    for (const auto& a : snapshot.attributes) if (a.attrelid == relation) rows.push_back(&a);
    std::sort(rows.begin(), rows.end(), [](const auto* a, const auto* b) { return a->attnum < b->attnum; });
    codec::Writer image;
    for (const auto* a : rows) {
        image.u(static_cast<uint16_t>(a->attnum), 2); image.text(a->attname);
        image.u(a->atttypid, 4); image.u(static_cast<uint32_t>(a->atttypmod), 4);
        image.u(a->attcollation, 4); image.u(static_cast<uint32_t>(a->attstattarget), 4);
        image.u(static_cast<uint32_t>(a->attndims), 4); image.flag(a->attisdropped);
        image.u(static_cast<unsigned char>(a->attgenerated), 1);
    }
    return image.finish();
}
} // namespace capture_detail

// One ANALYZE invocation owns the catalog, sample and comparator inputs.
// Existing native statistics continue to use their original full scan/format.
class ScalarStatisticsCapture {
    struct Attribute {
        size_t physicalColumn;
        Key key;
        Column statistics;
        dbms::Column storage;
        uint32_t equality, ordering;
        std::vector<ScalarSample> sample;
    };
    std::vector<Attribute> attributes_;
    std::filesystem::path schemaPath_;
    uint64_t schemaImage_ = 0, seen_ = 0;
    uint32_t relation_ = 0;
    std::string schema_, name_, attributeImage_;
    size_t capacity_ = 0;
    std::optional<size_t> selected_;
    std::optional<std::mt19937_64> random_;
public:
    ScalarStatisticsCapture(const TableSchema& table, const std::string& physical,
        const std::filesystem::path& schemaPath,
        const CatalogManager::MetadataSnapshot& snapshot) : schemaPath_(schemaPath) {
        auto logical = CatalogService::logicalName(physical);
        if (const auto* session = currentSession()) {
            const auto prefix = tempTablePrefix(*session, "");
            if (physical.rfind(prefix, 0) == 0) {
                logical.schema = sessionTempSchemaName(*session);
                logical.name = physical.substr(prefix.size());
            }
        }
        schema_ = logical.schema.empty() ? "public" : logical.schema; name_ = logical.name;
        uint32_t ns = 0;
        for (const auto& n : snapshot.namespaces) if (n.nspname == schema_) ns = n.oid;
        for (const auto& r : snapshot.relations)
            if (ns && r.relnamespace == ns && r.relname == name_ &&
                (r.relkind == 'r' || r.relkind == 'p' || r.relkind == 'm')) relation_ = r.oid;
        if (!relation_) return; // No invented identity for a legacy/native orphan.
        schemaImage_ = capture_detail::schemaImage(schemaPath_);
        attributeImage_ = capture_detail::attributeImage(snapshot, relation_);
        DatumMetadataFactory factory(snapshot);
        for (size_t i = 0; i < table.len; ++i) {
            const auto& storage = table.cols[i];
            if (storage.generatedKind == 'v') continue;
            for (const auto& a : snapshot.attributes) {
                if (a.attrelid != relation_ || a.attname != storage.dataName ||
                    a.attnum <= 0 || a.attisdropped || a.attstattarget == 0) continue;
                const auto type = factory.attribute(a);
                if (!type || type->kind != DatumKind::Scalar || type->enumType || storage.isArray) continue;
                const auto ops = capture_detail::scalarOperators(type->codecOid);
                if (!ops.first) continue; // Array/range/custom analysis is a separate owner.
                const auto genuine = std::find_if(snapshot.types.begin(), snapshot.types.end(),
                    [&](const auto& t) { return t.oid == type->codecOid && t.typnamespace == 11; });
                const auto& builtin = CatalogManager::builtinTypeRows();
                if (genuine == snapshot.types.end() || std::none_of(builtin.begin(), builtin.end(),
                    [&](const auto& t) { return t.oid == genuine->oid && t.typnamespace == 11 &&
                        t.typname == genuine->typname && t.typtype == genuine->typtype; })) continue;
                Column stats; stats.physicalRelation = table.physicalRelationId;
                stats.schemaGeneration = schemaImage_; stats.attributeType = type;
                stats.collation = a.attcollation; stats.target = a.attstattarget < 0 ? 100 : a.attstattarget;
                if (stats.target > 10000) throw DbError("22023", "statistics target exceeds 10000");
                if (!storage.isVariableLength) stats.averageWidth = storage.dsize;
                capacity_ = std::max(capacity_, size_t(stats.target) * 300);
                attributes_.push_back({i, {relation_, a.attnum,
                    table.partitionType != TableSchema::PartitionType::None}, std::move(stats), storage,
                    ops.first, ops.second, {}});
                break;
            }
        }
    }
    void beginRow() {
        ++seen_; selected_.reset();
        if (!capacity_) return;
        if (seen_ <= capacity_) selected_ = seen_ - 1;
        else {
            if (!random_) { std::random_device seed; random_.emplace((uint64_t(seed()) << 32) ^ seed()); }
            const auto slot = std::uniform_int_distribution<uint64_t>(0, seen_ - 1)(*random_);
            if (slot < capacity_) selected_ = slot;
        }
        if (selected_ && seen_ <= capacity_)
            for (auto& a : attributes_) a.sample.emplace_back();
    }
    void cell(size_t physicalColumn, const std::string& raw, bool isNull,
              const std::string& row, const TableSchema& table) {
        if (!selected_) return;
        for (auto& a : attributes_) {
            if (a.physicalColumn != physicalColumn) continue;
            ScalarSample cell; cell.ordinal = seen_ - 1;
            cell.value = ExprValue(a.storage.dataType, {}, isNull);
            if (!isNull) {
                size_t width = a.storage.dsize;
                if (a.storage.isVariableLength) {
                    const size_t position = table.fixedDataSize() + table.getVarColIndex(physicalColumn) * 4;
                    if (position + 4 > row.size()) throw DbError("XX001", "truncated analyzed variable datum");
                    uint16_t offset = 0, bytes = 0;
                    std::memcpy(&offset, row.data() + position, 2);
                    std::memcpy(&bytes, row.data() + position + 2, 2);
                    if (size_t(offset) + bytes > row.size()) throw DbError("XX001", "invalid analyzed variable datum span");
                    width = bytes; // Actual stored payload, including a TOAST reference when present.
                }
                if (width > INT32_MAX) throw DbError("54000", "analyzed datum width exceeds int32");
                cell.storedWidth = width;
                cell.tooWide = a.statistics.attributeType->codecSize < 0 && raw.size() + 4 > 1024;
                if (!cell.tooWide) cell.value.value = raw;
                cell.value.collation = a.storage.collation;
            }
            a.sample[*selected_] = std::move(cell);
        }
    }
    std::map<Key, Column> finish() {
        std::map<Key, Column> result;
        for (auto& a : attributes_) {
            a.statistics.totalRows = seen_;
            bool supported = true;
            for (const auto& s : a.sample) if (!s.value.isNull && !s.tooWide &&
                StorageEngine::compareValues(a.storage, s.value.value, false, s.value.value, false, "=")
                    != StorageEngine::PredicateTruth::True) { supported = false; break; }
            if (!supported) continue;
            const auto compare = [&a](const ExprValue& x, const ExprValue& y) {
                if (x.value == y.value) return 0;
                const auto equal = StorageEngine::compareValues(a.storage, x.value, false, y.value, false, "=");
                if (equal == StorageEngine::PredicateTruth::True) return 0;
                const auto less = StorageEngine::compareValues(a.storage, x.value, false, y.value, false, "<");
                if (equal == StorageEngine::PredicateTruth::Unknown || less == StorageEngine::PredicateTruth::Unknown)
                    throw DbError("0A000", "analyzed scalar has no applicable comparison");
                return less == StorageEngine::PredicateTruth::True ? -1 : 1;
            };
            if (auto stats = collectScalarStatistics(a.statistics, a.sample, a.equality, a.ordering,
                    compare, [] { checkForQueryInterrupt(); })) result.emplace(a.key, std::move(*stats));
        }
        return result;
    }
    bool hasIdentity() const { return relation_ != 0; }
    uint32_t relation() const { return relation_; }
    void verify(const CatalogManager::MetadataSnapshot& current) const {
        if (!relation_) return;
        uint32_t ns = 0;
        for (const auto& n : current.namespaces) if (n.nspname == schema_) ns = n.oid;
        const bool same = std::any_of(current.relations.begin(), current.relations.end(), [&](const auto& r) {
            return r.oid == relation_ && r.relnamespace == ns && r.relname == name_;
        });
        if (!same || capture_detail::schemaImage(schemaPath_) != schemaImage_ ||
            capture_detail::attributeImage(current, relation_) != attributeImage_)
            throw DbError("55000", "relation definition changed during ANALYZE");
    }
};
} // namespace dbms::analyzed_statistics

#pragma once

#include "catalog/AnalyzedStatistics.h"
#include "common/DbError.h"
#include <algorithm>
#include <cmath>
#include <functional>
#include <limits>
#include <numeric>

namespace dbms::analyzed_statistics {

// Inputs come from one real physical scan. Width is the stored datum's byte
// span, not its display length; wide values still contribute to width/NULL
// statistics but need not retain their payload. The scan ordinal survives
// reservoir replacement and is unrelated to the sample vector's position.
struct ScalarSample {
    uint64_t ordinal = 0;
    ExprValue value;
    uint32_t storedWidth = 0;
    bool tooWide = false;
};

// The caller supplies resolved equality/ordering roles and a comparator for
// the actual declaration/collation. No lexical fallback for unknown types.
// The formulas and slot applicability follow PostgreSQL REL_18_6 analyze.c;
// storage widths and the sampling owner belong to this engine.
inline std::optional<Column> collectScalarStatistics(
    Column column, const std::vector<ScalarSample>& sample,
    uint32_t equalityOperator, uint32_t orderingOperator,
    const std::function<int(const ExprValue&, const ExprValue&)>& compare,
    const std::function<void()>& interrupt = {}) {
    if (!column.attributeType || !column.attributeType->actualOid ||
        column.target < 0 || column.target > 10000 || column.averageWidth < 0 ||
        !std::isfinite(column.totalRows) || column.totalRows < sample.size())
        throw DbError("XX001", "invalid scalar statistics analysis input");
    if (!column.target || sample.empty()) return std::nullopt;
    if (!equalityOperator || !orderingOperator || !compare)
        throw DbError("XX001", "scalar statistics comparison role is absent");
    column.sampleRows = sample.size();
    column.nullRows = 0;
    column.slots.clear();
    uint64_t totalWidth = 0;
    size_t nonnull = 0, wide = 0;
    std::vector<size_t> values;
    values.reserve(sample.size());
    for (size_t i = 0; i < sample.size(); ++i) {
        if (interrupt && (i & 1023U) == 0) interrupt();
        const auto& cell = sample[i];
        if (cell.value.isNull) { ++column.nullRows; continue; }
        if (cell.storedWidth > INT32_MAX)
            throw DbError("XX001", "scalar statistics datum width exceeds int32");
        ++nonnull;
        totalWidth += cell.storedWidth;
        if (cell.tooWide) ++wide;
        else values.push_back(i);
    }
    column.nullFraction = double(column.nullRows) / sample.size();
    if (nonnull) column.averageWidth = static_cast<int32_t>(totalWidth / nonnull);
    column.distinctEstimate = 0;
    if (values.empty()) {
        if (nonnull) column.distinctEstimate = -(1.0 - column.nullFraction);
        return column;
    }

    // Physical rank includes only sortable non-NULL, non-wide sample values,
    // just as PG's values_cnt. A tie uses the original scan rank.
    std::sort(values.begin(), values.end(), [&](size_t a, size_t b) {
        return sample[a].ordinal < sample[b].ordinal;
    });
    std::vector<size_t> rank(sample.size());
    for (size_t i = 0; i < values.size(); ++i) {
        if (i && sample[values[i - 1]].ordinal == sample[values[i]].ordinal)
            throw DbError("XX001", "duplicate scalar statistics sample ordinal");
        rank[values[i]] = i;
    }
    size_t comparisons = 0;
    std::sort(values.begin(), values.end(), [&](size_t a, size_t b) {
        if (interrupt && (++comparisons & 1023U) == 0) interrupt();
        const int result = compare(sample[a].value, sample[b].value);
        return result ? result < 0 : rank[a] < rank[b];
    });
    struct Group { size_t first, count; };
    std::vector<Group> groups;
    double xy = 0;
    for (size_t i = 0; i < values.size(); ++i) {
        if (interrupt && (i & 1023U) == 0) interrupt();
        xy += double(i) * rank[values[i]];
        if (i && compare(sample[values[i - 1]].value, sample[values[i]].value) == 0)
            ++groups.back().count;
        else groups.push_back({i, 1});
    }
    const size_t repeated = std::count_if(groups.begin(), groups.end(),
        [](const Group& g) { return g.count > 1; });
    if (!repeated) column.distinctEstimate = -(1.0 - column.nullFraction);
    else if (!wide && repeated == groups.size()) column.distinctEstimate = groups.size();
    else {
        const double singleton = groups.size() - repeated + wide;
        const double distinct = singleton + repeated;
        const double population = column.totalRows * (1.0 - column.nullFraction);
        double estimate = nonnull * distinct /
            ((nonnull - singleton) + singleton * nonnull / population);
        estimate = std::min(population, std::max(distinct, estimate));
        column.distinctEstimate = std::floor(estimate + 0.5);
    }
    if (column.distinctEstimate > 0.1 * column.totalRows)
        column.distinctEstimate = -(column.distinctEstimate / column.totalRows);

    std::vector<size_t> common;
    for (size_t i = 0; i < groups.size(); ++i)
        if (groups[i].count > 1) common.push_back(i);
    std::stable_sort(common.begin(), common.end(), [&](size_t a, size_t b) {
        return groups[a].count > groups[b].count;
    });
    if (common.size() > static_cast<size_t>(column.target)) common.resize(column.target);
    // The full population needs no significance filter. For a sample, retain
    // a complete finite-domain list, or remove statistically weak tail items.
    const bool complete = common.size() == groups.size() && !wide &&
        column.distinctEstimate > 0;
    if (!complete && column.sampleRows != column.totalRows && column.totalRows > 1) {
        double populationDistinct = column.distinctEstimate;
        if (populationDistinct < 0) populationDistinct *= -column.totalRows;
        double preceding = 0;
        for (size_t i = 0; i + 1 < common.size(); ++i) preceding += groups[common[i]].count;
        while (!common.empty()) {
            double selectivity = std::clamp(1.0 - preceding / column.sampleRows -
                column.nullFraction, 0.0, 1.0);
            const double remaining = populationDistinct - (common.size() - 1);
            if (remaining > 1) selectivity /= remaining;
            const double count = groups[common.back()].count;
            const double population = column.totalRows, n = column.sampleRows;
            const double success = population * count / n;
            const double variance = n * success * (population - success) *
                (population - n) / (population * population * (population - 1));
            if (count > selectivity * n + 2 * std::sqrt(variance) + 0.5) break;
            common.pop_back();
            if (!common.empty()) preceding -= groups[common.back()].count;
        }
    }
    std::vector<bool> isCommon(groups.size(), false);
    if (!common.empty()) {
        Slot mcv; mcv.kind = Kind::MostCommon;
        mcv.comparisonOperator = equalityOperator; mcv.collation = column.collation;
        mcv.numbers.emplace(); mcv.values = Values{column.attributeType, {}};
        for (size_t g : common) {
            isCommon[g] = true;
            mcv.numbers->push_back(double(groups[g].count) / column.sampleRows);
            mcv.values->cells.push_back(sample[values[groups[g].first]].value);
        }
        column.slots.push_back(std::move(mcv));
    }
    size_t bounds = groups.size() - common.size();
    if (bounds > static_cast<size_t>(column.target)) bounds = column.target + 1;
    if (bounds >= 2) {
        std::vector<size_t> residual;
        for (size_t g = 0; g < groups.size(); ++g) if (!isCommon[g])
            for (size_t i = groups[g].first; i < groups[g].first + groups[g].count; ++i)
                residual.push_back(values[i]);
        Slot histogram; histogram.kind = Kind::Histogram;
        histogram.comparisonOperator = orderingOperator; histogram.collation = column.collation;
        histogram.values = Values{column.attributeType, {}};
        const size_t whole = (residual.size() - 1) / (bounds - 1);
        const size_t fraction = (residual.size() - 1) % (bounds - 1);
        size_t position = 0, remainder = 0;
        for (size_t i = 0; i < bounds; ++i) {
            histogram.values->cells.push_back(sample[residual[position]].value);
            position += whole; remainder += fraction;
            if (remainder >= bounds - 1) { ++position; remainder -= bounds - 1; }
        }
        column.slots.push_back(std::move(histogram));
    }
    if (values.size() > 1) {
        const double n = values.size(), sum = (n - 1) * n / 2;
        const double squares = (n - 1) * n * (2 * n - 1) / 6;
        Slot correlation; correlation.kind = Kind::Correlation;
        correlation.comparisonOperator = orderingOperator; correlation.collation = column.collation;
        correlation.numbers = std::vector<float>{float((n * xy - sum * sum) /
            (n * squares - sum * sum))};
        column.slots.push_back(std::move(correlation));
    }
    return column;
}
} // namespace dbms::analyzed_statistics

